/* ---------- predicted RGB response (new) ----------
   Ported from FS-Filter-Lab (CheeseCube312, MIT-licensed) \u2014 services/calculations.py
   + services/channel_mixer.py, cross-validated line-for-line against the real Python
   on identical synthetic inputs before this shipped (gains, per-wavelength response,
   and the channel-mixer matrix all matched to floating-point precision).

   CAMERA_QE, ILLUMINANTS, and REFLECTORS are now real data (see CAMERA_QE_REAL /
   ILLUMINANTS_REAL / REFLECTORS_REAL above) \u2014 sourced from CheeseCube312's
   Filter-Plotter-Data project, the same project the filter curves above are fitted
   against. This comment used to say those three were still empty placeholders;
   they aren't anymore, and this note is here so a future edit doesn't have to
   rediscover that by reading 900 lines of embedded numbers. What's still worth
   knowing: it's only ONE generic QE approximation, the human eye's own response,
   and one real scientific sensor (a monochrome astronomy CCD) \u2014 not a DSLR or
   mirrorless camera's QE, and only four real reflectors (all leaf/vegetation).
   The UI panel states this caveat directly rather than leaving it to a comment
   only a developer would see. */
const WL_LO=300, WL_HI=1100, WL_STEP=1;
const WL_GRID=[]; for(let l=WL_LO;l<=WL_HI;l+=WL_STEP)WL_GRID.push(l);
const CRGB_EPSILON=1e-6;
/* Real data from CheeseCube312/Filter-Plotter-Data, MIT-licensed, resampled onto
   this exact 300-1100nm/1nm grid the same way the Python reference does it
   (linear interp, NaN outside each source's own measured range — cross-checked
   against real np.interp() output point-for-point before this shipped, zero
   mismatches across all 801 points).

   Honest about what's actually here: ONE real consumer-relevant sensor curve
   does not exist in this dataset. What's included is a generic "Default CMOS"
   approximation, a real Human Eye photopic/scotopic-derived response, and one
   real scientific sensor — a Kodak KAF-8300, a monochrome astronomy CCD, not
   a DSLR or mirrorless camera. None of these should be read as "what my Canon
   sees" — the dropdown labels this explicitly, since silently implying broader
   camera coverage than actually exists here would be exactly the kind of
   invented-looking precision this whole project's data section explicitly
   argues against. */
const CAMERA_QE=CAMERA_QE_REAL;
const ILLUMINANTS=ILLUMINANTS_REAL;
const REFLECTORS=REFLECTORS_REAL;

function sampleStackTransmission(fs){ return WL_GRID.map(l=>stackT(l,fs)); }

function crgbValid(t){ return Array.isArray(t)&&t.length>0&&t.some(v=>Number.isFinite(v)); }

function computeWhiteBalanceGains(transmission,qe,illuminant){
  if(!crgbValid(transmission))return{R:1,G:1,B:1};
  const resp={};
  for(const ch of['R','G','B']){
    const qeCurve=qe[ch];
    if(!qeCurve){resp[ch]=NaN;continue;}
    let sum=0,any=false;
    for(let i=0;i<transmission.length;i++){
      const t=transmission[i],q=qeCurve[i],ill=illuminant[i];
      if(Number.isFinite(t)&&Number.isFinite(q)&&Number.isFinite(ill)){sum+=t*(q/100)*ill;any=true;}
    }
    resp[ch]=any?sum:NaN;
  }
  /* A white-balance GAIN is the multiplier that neutralises a channel: a
     channel the stack starves needs a gain ABOVE 1 to bring it back up.
     This used to return resp.ch / resp.G, which is the raw response RATIO —
     the reciprocal of the gain. The maths downstream was self-consistent
     (it divided rather than multiplied, so colours came out right), but the
     numbers shown under "White balance gains" were inverted relative to
     every raw converter and every other tool: a deep yellow stack, which
     starves blue, displayed B = 0.31 where a photographer expects ~3.2.
     Now returns true gains, normalised to G = 1, and everything downstream
     multiplies. */
  const g=resp.G;
  if(!Number.isFinite(g)||g<=CRGB_EPSILON)return{R:1,G:1,B:1};
  // A channel that sees essentially nothing would need an infinite gain;
  // clamp so the response chart and swatch stay finite and drawable.
  const MAX_GAIN=1e4;
  const gainOf=v=>(Number.isFinite(v)&&v>CRGB_EPSILON)?Math.min(g/v,MAX_GAIN):MAX_GAIN;
  return{R:gainOf(resp.R),G:1,B:gainOf(resp.B)};
}

function computeRgbResponse(transmission,qe,wbGains,visibleChannels,mixerMatrix,mixerEnabled){
  const n=transmission.length;
  if(!crgbValid(transmission)){
    const zero=new Array(n).fill(0);
    return{responses:{R:zero,G:zero,B:zero},maxResponse:0};
  }
  const responses={};
  let maxResponse=0;
  for(const ch of['R','G','B']){
    const qeCurve=qe[ch];
    if(!qeCurve||qeCurve.length!==n){responses[ch]=new Array(n).fill(0);continue;}
    const gain=Math.max(wbGains[ch]??1,CRGB_EPSILON); // now a multiplier, see computeWhiteBalanceGains
    const weighted=new Array(n);
    for(let i=0;i<n;i++){
      const t=transmission[i],q=qeCurve[i];
      const w=(Number.isFinite(t)&&Number.isFinite(q))?(t*(q/100))*gain*100:0;
      weighted[i]=w;
      if(w>maxResponse)maxResponse=w;
    }
    responses[ch]=(visibleChannels[ch]??true)?weighted:new Array(n).fill(0);
  }
  if(mixerEnabled){
    const mixed={R:[],G:[],B:[]};
    for(let i=0;i<n;i++){
      const r=responses.R[i],g=responses.G[i],b=responses.B[i];
      mixed.R.push(mixerMatrix[0][0]*r+mixerMatrix[0][1]*g+mixerMatrix[0][2]*b);
      mixed.G.push(mixerMatrix[1][0]*r+mixerMatrix[1][1]*g+mixerMatrix[1][2]*b);
      mixed.B.push(mixerMatrix[2][0]*r+mixerMatrix[2][1]*g+mixerMatrix[2][2]*b);
    }
    Object.assign(responses,mixed);
  }
  return{responses,maxResponse};
}

function applyChannelMixingToColor(rgb,matrix){
  const[r,g,b]=rgb;
  return[
    matrix[0][0]*r+matrix[0][1]*g+matrix[0][2]*b,
    matrix[1][0]*r+matrix[1][1]*g+matrix[1][2]*b,
    matrix[2][0]*r+matrix[2][1]*g+matrix[2][2]*b,
  ];
}

/* Ported from compute_reflector_color, cross-validated against the real Python
   to floating-point precision. Deliberately returns RAW values \u2014 same as the
   Python does \u2014 not clamped to a displayable range, since that normalisation
   is the Streamlit UI's job in the original and there's no equivalent to defer
   to here. crgbReflectorSwatch() below does that normalisation as this port's
   own addition, not something ported from the reference. */
function computeReflectorColor(reflector,transmission,qe,illuminant,wbGains,mixerMatrix,mixerEnabled){
  if(!crgbValid(transmission)||!reflector)return[0,0,0];
  const rgbResp={};
  for(const ch of['R','G','B']){
    const qeCurve=qe[ch];
    if(!qeCurve){rgbResp[ch]=0;continue;}
    let sum=0,any=false;
    for(let i=0;i<transmission.length;i++){
      const t=transmission[i],q=qeCurve[i],ill=illuminant[i],r=reflector[i];
      if(Number.isFinite(t)&&Number.isFinite(q)&&Number.isFinite(ill)&&Number.isFinite(r)){sum+=r*t*(q/100)*ill;any=true;}
    }
    rgbResp[ch]=any?sum:0;
  }
  let out=[0,0,0];
  ['R','G','B'].forEach((ch,i)=>{
    const gain=wbGains[ch]??1; // multiplier, as above
    out[i]=Number.isFinite(gain)?rgbResp[ch]*gain:rgbResp[ch];
  });
  if(mixerEnabled)out=applyChannelMixingToColor(out,mixerMatrix);
  return out;
}

/* This tool's own addition \u2014 not ported \u2014 for turning the raw values above
   into something a <div> background-color can actually show: normalise by
   the brightest of the three channels, then a standard sRGB-ish gamma so the
   swatch doesn't look artificially dark the way linear light does on screen. */
function crgbReflectorSwatch(rgb){
  const mx=Math.max(rgb[0],rgb[1],rgb[2],CRGB_EPSILON);
  const gamma=v=>Math.pow(Math.max(0,Math.min(1,v/mx)),1/2.2);
  return rgb.map(v=>Math.round(gamma(v)*255));
}

function crgbReadMatrix(){
  const id=s=>parseFloat($(s).value)||0;
  return[
    [id('cmRR'),id('cmRG'),id('cmRB')],
    [id('cmGR'),id('cmGG'),id('cmGB')],
    [id('cmBR'),id('cmBG'),id('cmBB')],
  ];
}

function crgbPopulateDropdowns(){
  const qeSel=$('crgbQE'), illSel=$('crgbIll'), reflSel=$('crgbRefl');
  if(!qeSel||!illSel)return;
  qeSel.innerHTML='';
  Object.keys(CAMERA_QE).forEach(name=>{
    const opt=document.createElement('option'); opt.value=name; opt.textContent=name; qeSel.appendChild(opt);
  });
  illSel.innerHTML='';
  Object.keys(ILLUMINANTS).forEach(name=>{
    const opt=document.createElement('option'); opt.value=name; opt.textContent=name; illSel.appendChild(opt);
  });
  if(reflSel){
    reflSel.innerHTML='';
    Object.keys(REFLECTORS).forEach(name=>{
      const opt=document.createElement('option'); opt.value=name; opt.textContent=name; reflSel.appendChild(opt);
    });
  }
}

function drawCrgbChart(responses,maxResponse,targetCanvas,forceW,forceH){
  const cv=targetCanvas||$('crgbChart');if(!cv)return null;
  let W,H,dpr;
  if(forceW&&forceH){
    // explicit size — used by the PNG export, which must work even when the
    // panel this chart lives in has never been expanded (a collapsed
    // <details> gives its canvas a zero-size bounding rect, so the on-screen
    // canvas would otherwise be 0x0 and export as nothing at all)
    W=forceW;H=forceH;dpr=Math.max(1,W/700);
  }else{
    const rect=cv.getBoundingClientRect();dpr=window.devicePixelRatio||1;
    W=Math.max(1,Math.round(rect.width*dpr));H=Math.max(1,Math.round(rect.height*dpr));
    if(W<=1||H<=1)return null; // panel collapsed — nothing meaningful to draw
  }
  if(cv.width!==W||cv.height!==H){cv.width=W;cv.height=H;}
  const cx=cv.getContext('2d');
  cx.clearRect(0,0,W,H);
  cx.fillStyle=chartTheme().bg;cx.fillRect(0,0,W,H);
  const pad={l:34*dpr,r:8*dpr,t:8*dpr,b:20*dpr};
  const yMax=Math.max(maxResponse,1e-6)*1.08;
  const x=l=>pad.l+(l-WL_LO)/(WL_HI-WL_LO)*(W-pad.l-pad.r);
  const y=v=>pad.t+(1-v/yMax)*(H-pad.t-pad.b);

  // thin QE-tinted strip along the top showing roughly where R/G/B peak,
  // mirroring the reference report's little illuminant/QE bar
  cx.strokeStyle='rgba(84,64,42,.4)';cx.lineWidth=1*dpr;
  for(let t=0;t<=1.0001;t+=0.5){
    const yy=Math.round(y(t*yMax))+.5;
    cx.beginPath();cx.moveTo(pad.l,yy);cx.lineTo(W-pad.r,yy);cx.stroke();
    cx.fillStyle='#7a6a52';cx.font=(9*dpr)+'px "JetBrains Mono",monospace';
    cx.textAlign='right';cx.textBaseline='middle';
    cx.fillText(Math.round(t*yMax),pad.l-4*dpr,yy);
  }
  for(let l=300;l<=1100;l+=200){
    const xx=Math.round(x(l))+.5;
    cx.beginPath();cx.moveTo(xx,pad.t);cx.lineTo(xx,H-pad.b);cx.stroke();
    cx.textAlign='center';cx.textBaseline='top';
    cx.fillText(l,xx,H-pad.b+4*dpr);
  }

  const COLORS={R:'#e05a4a',G:'#5ec26a',B:'#4a8fe0'};
  ['R','G','B'].forEach(ch=>{
    const arr=responses[ch];if(!arr)return;
    cx.beginPath();
    WL_GRID.forEach((l,i)=>{const xx=x(l),yy=y(arr[i]);i?cx.lineTo(xx,yy):cx.moveTo(xx,yy);});
    cx.strokeStyle=COLORS[ch];cx.lineWidth=1.8*dpr;cx.stroke();
  });
  return cv;
}

/* Renders the sensor-weighted response chart fresh into an offscreen canvas
   at an explicit size, recomputing from the current selection rather than
   depending on the on-screen one — so the PNG export contains it whether or
   not the user has ever opened the "Predicted RGB response" panel. Returns
   null when there's nothing to draw (no selection, or no sensor/illuminant). */
function crgbRenderForExport(W,H){
  const fs=selected.map(id=>FILTERS.find(f=>f.id===id)).filter(Boolean);
  if(!fs.length)return null;
  const qeSel=$('crgbQE'),illSel=$('crgbIll');
  if(!qeSel||!illSel)return null;
  const qe=CAMERA_QE[qeSel.value],illuminant=ILLUMINANTS[illSel.value];
  if(!qe||!illuminant)return null;
  const transmission=sampleStackTransmission(fs);
  const gains=computeWhiteBalanceGains(transmission,qe,illuminant);
  const mixerOn=$('cmEnabled')?$('cmEnabled').checked:false;
  const{responses,maxResponse}=computeRgbResponse(transmission,qe,gains,{R:true,G:true,B:true},crgbReadMatrix(),mixerOn);
  const off=document.createElement('canvas');
  drawCrgbChart(responses,maxResponse,off,W,H);
  return{canvas:off,gains,qeName:qeSel.value,illName:illSel.value};
}

function crgbUpdate(){
  const status=$('crgbStatus');
  const fs=selected.map(id=>FILTERS.find(f=>f.id===id)).filter(Boolean);  // same resolution the app itself uses
  if(fs.length===0){
    status.style.display='block'; status.style.color='var(--muted)';
    status.textContent='Select at least one filter above to see a predicted response.';
    $('crgbResult').style.display='none';
    $('crgbReflectorWrap').style.display='none';
    $('crgbChartWrap').style.display='none';
    return;
  }
  const qeName=$('crgbQE').value, illName=$('crgbIll').value;
  const qe=CAMERA_QE[qeName], illuminant=ILLUMINANTS[illName];
  if(!qe||!illuminant){ status.style.display='none'; $('crgbResult').style.display='none'; $('crgbReflectorWrap').style.display='none'; $('crgbChartWrap').style.display='none'; return; }
  status.style.display='none';
  $('crgbResult').style.display='';
  $('crgbChartWrap').style.display='';
  /* Auto-expand this panel the first time a stack is selected. The response
     chart is a RESULT, not an explanation, and burying results inside a
     collapsed <details> meant it went unnoticed entirely — opened once, then
     left alone so a deliberate collapse by the user is respected. */
  const det=$('crgbDetails');
  if(det&&!det.open&&!det.dataset.autoOpened){det.open=true;det.dataset.autoOpened='1';}
  const transmission=sampleStackTransmission(fs);
  const gains=computeWhiteBalanceGains(transmission,qe,illuminant);
  const mixerOn=$('cmEnabled').checked;
  const matrix=crgbReadMatrix();
  const{responses,maxResponse}=computeRgbResponse(transmission,qe,gains,{R:true,G:true,B:true},matrix,mixerOn);
  $('crgbGainR').textContent=gains.R.toFixed(3);
  $('crgbGainG').textContent=gains.G.toFixed(3);
  $('crgbGainB').textContent=gains.B.toFixed(3);
  drawCrgbChart(responses,maxResponse);

  const reflName=$('crgbRefl')&&$('crgbRefl').value;
  const reflector=reflName&&REFLECTORS[reflName];
  if(reflector){
    $('crgbReflectorWrap').style.display='';
    const raw=computeReflectorColor(reflector,transmission,qe,illuminant,gains,matrix,mixerOn);
    const[r,g,b]=crgbReflectorSwatch(raw);
    $('crgbSwatch').style.background=`rgb(${r},${g},${b})`;
    // Normalised the SAME way the swatch already is, rather than showing
    // the raw physical integration units directly. Those raw numbers scale
    // with how much total light a filter passes -- a wide-passband filter
    // like DB850 (full visible + 850nm NIR) naturally integrates to several
    // times what a narrow long-pass does, with completely correct maths
    // behind it, but two separate people independently read the resulting
    // large numbers as "this looks broken" before ever getting to that
    // explanation. The relative ratio between channels is the only part
    // that was ever meaningful to a reader anyway -- showing that directly
    // avoids the confusion instead of footnoting past it.
    const rawMax = Math.max(raw[0], raw[1], raw[2], 1e-6);
    $('crgbReflVal').textContent=`R:${(raw[0]/rawMax).toFixed(2)}  G:${(raw[1]/rawMax).toFixed(2)}  B:${(raw[2]/rawMax).toFixed(2)} (relative to the brightest channel)`;
  } else {
    $('crgbReflectorWrap').style.display='none';
  }
}

/* Verifies the wiring end-to-end with an OBVIOUSLY synthetic test swatch \u2014
   never presented as a real camera prediction, only as "the maths runs". */
function crgbSelfTest(){
  const testQE={R:WL_GRID.map(()=>60),G:WL_GRID.map(()=>60),B:WL_GRID.map(()=>60)};
  const testIll=WL_GRID.map(()=>1);
  const fs=selected.map(id=>FILTERS.find(f=>f.id===id)).filter(Boolean);
  const transmission=sampleStackTransmission(fs);
  const gains=computeWhiteBalanceGains(transmission,testQE,testIll);
  const{maxResponse}=computeRgbResponse(transmission,testQE,gains,{R:true,G:true,B:true},crgbReadMatrix(),$('cmEnabled').checked);
  if($('crgbSelfTestMsg'))$('crgbSelfTestMsg').textContent=`Self-test ran on a flat synthetic sensor (not a real camera) \u2014 max response ${maxResponse.toFixed(1)}. Confirms the pipeline is wired correctly; this number means nothing about any real camera.`;
}

['crgbQE','crgbIll','crgbRefl','cmEnabled','cmRR','cmRG','cmRB','cmGR','cmGG','cmGB','cmBR','cmBG','cmBB'].forEach(id=>{
  const el=$(id);
  if(el)el.addEventListener(el.tagName==='SELECT'||el.type==='checkbox'?'change':'input',crgbUpdate);
});
/* Expanding the panel by hand gives its canvas a real size for the first
   time — without this the chart stays blank until some other input changes. */
if($('crgbDetails'))$('crgbDetails').addEventListener('toggle',()=>{if($('crgbDetails').open)crgbUpdate();});
if($('selfTestBtn'))$('selfTestBtn').addEventListener('click',renderSelfTest);
crgbPopulateDropdowns();
draw();
if(typeof crgbUpdate==="function")crgbUpdate();
